const families=[
{name:'Documents',inputs:['pdf','docx','md','html','txt','epub','rtf','odt'],targets:['docx','md','html','txt','rtf','epub','odt'],engine:'Pandoc',title:'Move between document formats.',note:'Styles and metadata may change. Document conversion is semantic, rather than pixel-perfect.'},
{name:'Images',inputs:['png','jpg','jpeg','webp','bmp','tiff','ico','tga','psd','svg'],targets:['webp','png','jpg','ico','bmp','tiff','tga','pdf'],engine:'ImageMagick',title:'Make an image fit its next use.',note:'Convert raster images or rasterize SVG. JPEG output flattens transparency onto white.'},
{name:'Video',inputs:['mp4','webm','mkv','mov','avi','flv','wmv','m4v','ts','3gp','ogv','vob'],targets:['mp4','webm','mkv','mov','avi','gif','mp3','wav','flac','srt'],engine:'FFmpeg + FFprobe',title:'Transcode video or extract a track.',note:'Quality depends on the selected codec. Audio extraction needs an audio track; SRT extraction needs an internal subtitle track. GIF has no audio.'},
{name:'Audio',inputs:['mp3','wav','flac','aac','ogg','m4a','opus','wma','aiff'],targets:['mp3','wav','flac','aac','ogg','m4a','opus'],engine:'FFmpeg + FFprobe',title:'Choose a format for listening or editing.',note:'Lossless output cannot restore detail already lost in a compressed source. Lossy encoding can reduce quality.'},
{name:'Data',inputs:['csv','json','xlsx','yaml','xml','toml','sqlite','db','bib','ics','log'],targets:['json','csv','yaml','toml','xml','xlsx','sql'],engine:'Built-in Rust tools',title:'Reshape data for the next tool.',note:'XLSX uses the first worksheet only. Types can change between formats. Formula-like CSV cells are prefixed with an apostrophe.'},
{name:'Archives',inputs:['folder','zip','tar','gz','tgz'],targets:['zip','folder'],engine:'Built-in Rust tools',title:'Package a folder. Unpack a ZIP.',note:'Links and special files are excluded. Archive limits: 10,000 entries, 64 path levels, and 5 GiB expanded data.'}
];
let active=0;const from=document.querySelector('#input-format'),to=document.querySelector('#output-format'),categories=document.querySelector('.categories');
function targets(f,input){if(f.name==='Archives')return input==='zip'?['folder']:['zip'];if(f.name==='Data'&&['sqlite','db','bib','ics','log'].includes(input))return ['json'];return f.targets.filter(t=>t!==input&&!(input==='jpeg'&&t==='jpg')&&!(t==='sql'&&input!=='csv'));}
function options(el,values){el.replaceChildren(...values.map(v=>{const o=document.createElement('option');o.value=v;o.textContent=v==='folder'?'FOLDER':v.toUpperCase();return o;}));}
function describe(){const f=families[active];document.querySelector('#pair-title').textContent=f.title;document.querySelector('#pair-note').textContent=from.value==='pdf'?'PDF conversion extracts text and layout. Complex layouts, fonts, forms, and images can shift or be lost.':f.note;document.querySelector('#pair-engine').textContent=from.value==='pdf'?(to.value==='txt'?'Poppler · pdftotext':'Poppler · pdftohtml'):f.engine;}
function updateTargets(){const previous=to.value;options(to,targets(families[active],from.value));if([...to.options].some(o=>o.value===previous))to.value=previous;describe();}
function choose(index){active=index;document.querySelector('#family-label').textContent=families[index].name;[...categories.children].forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));options(from,families[index].inputs);updateTargets();}
families.forEach((f,i)=>{const b=document.createElement('button');b.type='button';b.textContent=f.name;b.setAttribute('aria-pressed','false');b.addEventListener('click',()=>choose(i));categories.append(b);});from.addEventListener('change',updateTargets);to.addEventListener('change',describe);choose(0);
